SELECT SUM(amount_cents) / 100.0 AS total_completed_revenue_usd
FROM orders_v2
WHERE status = 'c';

SELECT SUM(amount_cents) / 100.0 AS total_refunded_usd
FROM payments
WHERE state = 'refunded';

SELECT COUNT(*) AS active_products
FROM public.products
WHERE active = true;

SELECT COUNT(*) AS active_products
FROM products
WHERE active = true;

SELECT COUNT(*) AS cancelled_orders
FROM orders_v2
WHERE status = 'x';

SELECT AVG(price_cents) / 100.0 AS avg_price_usd
FROM products
WHERE price_cents IS NOT NULL;
